mapper.select:
SELECT log.id, log.tenant_id, log.user_id, log.username, log.file_id, log.file_name, CASE WHEN log.file_size IS NOT NULL AND log.file_size > 0 THEN log.file_size ELSE ( SELECT meta.file_size FROM sys_file_metadata meta WHERE meta.file_id = log.file_id AND meta.status = 1 AND meta.file_size > 0 ORDER BY meta.id DESC LIMIT 1 ) END AS file_size, log.source, log.request_path, log.client_ip, log.create_time FROM sys_file_download_log log WHERE log.del_flag = 0
AND log.user_id = #{userId}
AND log.file_name LIKE CONCAT('%', #{query.fileName}, '%')
AND log.source = #{query.source}
AND log.username LIKE CONCAT('%', #{query.username}, '%')
AND log.create_time >= #{query.startTime}
AND log.create_time <= #{query.endTime}
ORDER BY log.create_time DESC, log.id DESC
